pub fn config(port: &str, database: &str) -> Result<u16, &'static str> {
    if port.is_empty() || !port.bytes().all(|b| b.is_ascii_digit()) {
        return Err("port");
    }
    let n = port.parse::<u16>().map_err(|_| "port")?;
    if n < 1024 {
        return Err("port");
    }
    if database.is_empty() || database.chars().any(char::is_whitespace)
    {
        return Err("database");
    }
    Ok(n)
}

fn main() {
    assert_eq!(config("8080", "tasks.db"), Ok(8080), "case 1");
    assert_eq!(config("0", "tasks.db"), Err("port"), "case 2");
    assert_eq!(config("65536", "tasks.db"), Err("port"), "case 3");
    assert_eq!(config("+8080", "tasks.db"), Err("port"), "case 4");
    assert_eq!(config("8080", ""), Err("database"), "case 5");
    assert_eq!(config("8080", "bad path"), Err("database"), "case 6");
    assert_eq!(config("65535", "db"), Ok(65535), "case 7");
    println!("worked example passed");
}

